async function profile(){const u=await user();if(!u){shell('<section class="section wrap"><div class="form"><h2>LOGIN REQUIRED</h2><p><a class="btn primary" href="login.html">LOGIN</a></p></div></section>');return}const [pr,st,un,cs]=await Promise.all([crSupabase.from("podcast_member_profiles").select("*").eq("user_id",u.id).maybeSingle(),crSupabase.from("podcast_member_profile_stats").select("*").eq("user_id",u.id).maybeSingle(),crSupabase.from("podcast_profile_achievement_unlocks").select("achievement_key,unlocked_at").eq("user_id",u.id).order("unlocked_at",{ascending:false}),crSupabase.from("podcast_creator_stats").select("*").eq("user_id",u.id).maybeSingle()]);const p=pr.data||{},x=st.data||{},ach=un.data||[],points=Number(x.crowpoints||0),score=points+ach.length*100+Number(x.total_plays||0)*2+Number(x.episode_comments||0)*5+Number(x.episode_reactions||0)*2+Number(x.member_followers||0)*5,level=Math.max(1,Math.floor(score/500)+1),tier=level>=10?"LEGEND":level>=7?"VETERAN":level>=4?"ESTABLISHED":"RISING";const avatar=p.avatar_url?'<img src="'+esc(p.avatar_url)+'" alt="" style="width:96px;height:96px;border-radius:50%;object-fit:cover;border:1px solid rgba(255,255,255,.2)">':'<div class="card" style="width:96px;height:96px;border-radius:50%;display:grid;place-items:center;font-size:2rem">🎙️</div>';shell('<section class="section wrap"><div class="studioHero">'+avatar+'<span class="eyebrow">CROWRULES PODCASTING · MEMBER PROFILE 2.0</span><h1>'+esc(p.display_name||u.email.split("@")[0])+'</h1><p>@'+esc(p.username||"member")+(p.tagline?" · "+esc(p.tagline):"")+'</p>'+(p.bio?'<p>'+esc(p.bio)+'</p>':"")+'<div class="actions"><a class="btn primary" href="edit-profile.html">EDIT PROFILE</a><a class="btn" href="reputation.html">LEVEL '+level+' · '+tier+'</a><a class="btn" href="achievements.html">'+ach.length+' ACHIEVEMENTS</a></div></div><div class="grid"><div class="card"><small>REPUTATION</small><h2 class="glow">'+score.toLocaleString()+'</h2></div><div class="card"><small>CROWPOINTS</small><h2>'+points.toLocaleString()+'</h2></div><div class="card"><small>LISTENING</small><h2>'+Math.floor(Number(x.listening_seconds||0)/3600)+'h</h2></div><div class="card"><small>NETWORK</small><h2>'+Number(x.member_followers||0)+' / '+Number(x.member_following||0)+'</h2><small>followers / following</small></div></div><div class="grid"><div class="card"><span class="eyebrow">LISTENER</span><h3>'+Number(x.total_plays||0).toLocaleString()+' plays</h3><p>'+Number(x.episode_comments||0)+' comments · '+Number(x.episode_reactions||0)+' reactions</p><a class="btn" href="my-library.html">MY LIBRARY</a></div><div class="card"><span class="eyebrow">CREATOR</span><h3>'+Number(x.published_podcasts||0)+' podcasts · '+Number(x.published_episodes||0)+' episodes</h3><p>'+Number(cs.data?.total_plays||0).toLocaleString()+' creator plays</p><a class="btn" href="podcast-dashboard.html">CREATOR STUDIO</a></div><div class="card"><span class="eyebrow">PROFILE</span><h3>'+(p.is_public?"PUBLIC":"PRIVATE")+'</h3><p>'+(p.location?esc(p.location)+" · ":"")+(p.website_url?'<a href="'+esc(p.website_url)+'" target="_blank" rel="noopener">Website</a>':"")+'</p><a class="btn" href="member-profile.html?id='+encodeURIComponent(u.id)+'">VIEW PUBLIC PROFILE</a></div></div></section>')}
async function editProfile(){const u=await user();if(!u){location.href="login.html";return}const {data:p}=await crSupabase.from("podcast_member_profiles").select("*").eq("user_id",u.id).maybeSingle();shell('<section class="section wrap"><div class="form"><span class="eyebrow">MEMBER IDENTITY</span><h2>EDIT <span class="glow">PROFILE</span></h2><div class="field"><label>Display name</label><input id="displayName" value="'+esc(p?.display_name||"")+'"></div><div class="field"><label>Username</label><input id="username" value="'+esc(p?.username||"")+'"></div><div class="field"><label>Tagline</label><input id="tagline" value="'+esc(p?.tagline||"")+'"></div><div class="field"><label>Bio</label><textarea id="bio" rows="5">'+esc(p?.bio||"")+'</textarea></div><div class="field"><label>Avatar URL</label><input id="avatarUrl" value="'+esc(p?.avatar_url||"")+'" placeholder="https://..."></div><div class="field"><label>Cover URL</label><input id="coverUrl" value="'+esc(p?.cover_url||"")+'" placeholder="https://..."></div><div class="field"><label>Location</label><input id="location" value="'+esc(p?.location||"")+'"></div><div class="field"><label>Website</label><input id="websiteUrl" value="'+esc(p?.website_url||"")+'" placeholder="https://..."></div><div class="field"><label>Interests</label><input id="interests" value="'+esc(p?.interests||"")+'" placeholder="Film, music, sports..."></div><div class="field"><label>Profile visibility</label><select id="isPublic"><option value="true" '+(p?.is_public!==false?"selected":"")+'>Public</option><option value="false" '+(p?.is_public===false?"selected":"")+'>Private</option></select></div><button class="btn primary" onclick="saveProfile()">SAVE PROFILE</button></div></section>')}
async function saveProfile(){const u=await user();if(!u){location.href="login.html";return}const row={user_id:u.id,display_name:displayName.value.trim(),username:username.value.trim(),tagline:tagline.value.trim(),bio:bio.value.trim(),avatar_url:avatarUrl.value.trim()||null,cover_url:coverUrl.value.trim()||null,location:location.value.trim()||null,website_url:websiteUrl.value.trim()||null,interests:interests.value.trim()||null,is_public:isPublic.value==="true",updated_at:new Date().toISOString()};const {error}=await crSupabase.from("podcast_member_profiles").upsert(row,{onConflict:"user_id"});alert(error?error.message:"Profile saved.");if(!error)location.href="profile.html"}
async function createPodcast(){const u=await user();if(!u){location.href="login.html";return}const cats=await crSupabase.from("podcast_categories").select("id,name").order("name");shell('<section class="section wrap"><div class="form"><span class="eyebrow">CREATOR STUDIO</span><h2>CREATE YOUR <span class="glow">PODCAST</span></h2><p>Create a draft show. You can add episodes from Creator Studio after creation.</p><div class="field"><label>Podcast name</label><input id="title"></div><div class="field"><label>Slug</label><input id="slug" placeholder="my-podcast"></div><div class="field"><label>Description</label><textarea id="description" rows="5"></textarea></div><div class="field"><label>Category</label><select id="category">'+(cats.data||[]).map(c=>'<option value="'+esc(c.name)+'">'+esc(c.name)+'</option>').join("")+'</select></div><div class="field"><label>Artwork URL</label><input id="artwork" placeholder="https://..."></div><button class="btn primary" onclick="savePodcast()">CREATE PODCAST</button><div id="studioStatus" class="status"></div></div></section>')}
async function savePodcast(){const u=await user(),c=await creatorFor(u);if(!c){alert("Your Universal CrowRules creator profile is not linked yet. A creator record must be connected to your member account before publishing.");return}const clean=slug.value.trim().toLowerCase().replace(/[^a-z0-9-]+/g,"-").replace(/^-+|-+$/g,"");const row={creator_id:c.id,title:title.value.trim(),slug:clean,description:description.value.trim(),category:category.value,artwork_url:artwork.value.trim()||null,status:"draft"};const {data,error}=await crSupabase.from("podcasts").insert(row).select("id").single();if(error){alert(error.message);return}location.href="podcast-dashboard.html?id="+encodeURIComponent(data.id)}
async function studio(){const u=await user();if(!u){location.href="login.html";return}const c=await creatorFor(u);if(!c){shell('<section class="section wrap"><div class="form"><span class="eyebrow">CREATOR STUDIO</span><h2>CREATOR <span class="glow">PROFILE NEEDED</span></h2><p>Your CrowRules member account is not linked to a creator record yet.</p><a class="btn primary" href="profile.html">BACK TO PROFILE</a></div></section>');return}const {data:ps}=await crSupabase.from("podcasts").select("*").eq("creator_id",c.id).order("created_at",{ascending:false});const ids=(ps||[]).map(x=>x.id);let es=[];if(ids.length){const r=await crSupabase.from("podcast_episodes").select("*").in("podcast_id",ids).order("created_at",{ascending:false});es=r.data||[]}shell('<section class="section wrap"><div class="studioHero"><span class="eyebrow">CREATOR STUDIO 2.0</span><h1>BUILD YOUR <span class="glow">SHOW</span></h1><p>Manage your podcasts and release episodes from one cinematic workspace.</p><div class="actions"><a class="btn primary" href="create-podcast.html">＋ NEW PODCAST</a><a class="btn" href="upload-episode.html">UPLOAD EPISODE</a><a class="btn" href="my-podcasts.html">MY PODCASTS</a><a class="btn" href="my-episodes.html">MY EPISODES</a></div></div><div class="stats"><div class="card"><small>PODCASTS</small><h2 class="glow">'+(ps||[]).length+'</h2></div><div class="card"><small>EPISODES</small><h2>'+(es||[]).length+'</h2></div><div class="card"><small>PUBLISHED</small><h2>'+((ps||[]).filter(x=>x.status==="published").length+(es||[]).filter(x=>x.status==="published").length)+'</h2></div><div class="card"><small>TOTAL PLAYS</small><h2>'+Number((ps||[]).reduce((n,x)=>n+Number(x.total_plays||0),0)+(es||[]).reduce((n,x)=>n+Number(x.play_count||0),0)).toLocaleString()+'</h2></div></div><h2>Your <span class="glow">Podcasts</span></h2><div class="grid">'+((ps||[]).map(p=>'<div class="card"><div class="actions" style="justify-content:space-between"><span class="pill">'+esc(p.status)+'</span><small>'+Number(p.total_plays||0).toLocaleString()+' plays</small></div><h3>'+esc(p.title)+'</h3><p>'+esc(p.description||"")+'</p><div class="actions"><a class="btn primary" href="upload-episode.html?podcast_id='+encodeURIComponent(p.id)+'">UPLOAD EPISODE</a><a class="btn" href="podcast.html?id='+encodeURIComponent(p.id)+'">VIEW</a></div></div>').join("")||'<p>No podcasts yet.</p>')+'</div><h2 style="margin-top:55px">Recent <span class="glow">Episodes</span></h2><div class="grid">'+(es.slice(0,12).map(e=>'<div class="card"><div class="actions" style="justify-content:space-between"><span class="pill">'+esc(e.status)+'</span><small>'+Number(e.play_count||0).toLocaleString()+' plays</small></div><h3>'+esc(e.title)+'</h3><p>'+esc(e.description||"")+'</p><small>'+(e.audio_url?"✓ Audio ready":"○ Audio missing")+'</small></div>').join("")||'<p>No episodes yet.</p>')+'</div></section>')}
async function uploadEpisode(){const u=await user();if(!u){location.href="login.html";return}const c=await creatorFor(u);if(!c){alert("Creator profile required.");return}const {data:ps}=await crSupabase.from("podcasts").select("id,title").eq("creator_id",c.id).order("title");const selected=new URLSearchParams(location.search).get("podcast_id");shell('<section class="section wrap"><div class="form uploadForm"><span class="eyebrow">CREATOR STUDIO • EPISODE UPLOAD</span><h2>UPLOAD <span class="glow">EPISODE</span></h2><p class="notice">Audio uploads are limited by the current podcast-audio bucket to 500 MB. Supabase recommends resumable TUS uploads for files larger than 6 MB.</p><div class="field"><label>Podcast</label><select id="episodePodcast">'+(ps||[]).map(p=>'<option value="'+p.id+'" '+(p.id===selected?"selected":"")+'>'+esc(p.title)+'</option>').join("")+'</select></div><div class="field"><label>Episode title</label><input id="episodeTitle"></div><div class="field"><label>Slug</label><input id="episodeSlug" placeholder="episode-1"></div><div class="field"><label>Description</label><textarea id="episodeDescription" rows="4"></textarea></div><div class="field"><label>Season</label><input id="seasonNumber" type="number" value="1" min="1"></div><div class="field"><label>Episode number</label><input id="episodeNumber" type="number" value="1" min="1"></div><div class="field"><label>Show notes</label><textarea id="showNotes" rows="5"></textarea></div><div class="field"><label>Audio file</label><input id="audioFile" type="file" accept="audio/*,.m4a,.mp3,.wav,.ogg,.webm"><small>Maximum: 500 MB</small></div><div id="uploadProgress" class="uploadProgress"><div id="uploadBar"></div></div><p id="uploadStatus" class="status"></p><button class="btn primary" onclick="startEpisodeUpload()">CREATE DRAFT + UPLOAD</button></div></section>')}
async function startEpisodeUpload(){const u=await user(),file=audioFile.files[0];if(!u||!file)return alert("Log in and choose an audio file.");if(file.size>500*1024*1024)return alert("This file is larger than the current 500 MB podcast-audio bucket limit.");if(!file.type.startsWith("audio/")&&!/\.(mp3|m4a|wav|ogg|webm)$/i.test(file.name))return alert("Choose a supported audio file.");const podcastId=episodePodcast.value;const slug=(episodeSlug.value.trim()||episodeTitle.value.trim()).toLowerCase().replace(/[^a-z0-9-]+/g,"-").replace(/^-+|-+$/g,"");const row={podcast_id:podcastId,title:episodeTitle.value.trim(),slug,description:episodeDescription.value.trim(),episode_number:Number(episodeNumber.value)||1,season_number:Number(seasonNumber.value)||1,show_notes:showNotes.value.trim(),status:"draft"};setUploadStatus("Creating episode draft…");const ins=await crSupabase.from("podcast_episodes").insert(row).select("id").single();if(ins.error){setUploadStatus(ins.error.message);return}const episodeId=ins.data.id;const safe=file.name.replace(/[^a-zA-Z0-9._-]+/g,"-");const objectPath=u.id+"/"+podcastId+"/"+episodeId+"-"+safe;const session=(await crSupabase.auth.getSession()).data.session;if(!session){setUploadStatus("Your session expired. Please log in again.");return}if(!window.tus){setUploadStatus("Upload library failed to load.");return}setUploadStatus("Starting resumable upload…");const upload=new tus.Upload(file,{endpoint:"https://cevylpnoexugwgygvtgu.storage.supabase.co/storage/v1/upload/resumable",retryDelays:[0,3000,5000,10000,20000],headers:{authorization:"Bearer "+session.access_token,apikey:CROWRULES_CONFIG.supabaseAnonKey,"x-upsert":"false"},uploadDataDuringCreation:true,removeFingerprintOnSuccess:true,chunkSize:6*1024*1024,metadata:{bucketName:"podcast-audio",objectName:objectPath,contentType:file.type||"audio/mpeg",cacheControl:"3600"},onProgress:(up,total)=>{const pct=Math.round(up/total*100);document.getElementById("uploadBar").style.width=pct+"%";setUploadStatus("Uploading… "+pct+"%")},onError:async err=>{await crSupabase.from("podcast_episode_uploads").insert({episode_id:episodeId,uploaded_by:u.id,storage_bucket:"podcast-audio",storage_path:objectPath,original_filename:file.name,mime_type:file.type,file_size_bytes:file.size,status:"failed",error_message:String(err)});setUploadStatus("Upload failed: "+err.message)},onSuccess:async()=>{const pub=crSupabase.storage.from("podcast-audio").getPublicUrl(objectPath).data.publicUrl;const up=await crSupabase.from("podcast_episode_uploads").insert({episode_id:episodeId,uploaded_by:u.id,storage_bucket:"podcast-audio",storage_path:objectPath,original_filename:file.name,mime_type:file.type,file_size_bytes:file.size,status:"completed"});const ep=await crSupabase.from("podcast_episodes").update({audio_url:pub}).eq("id",episodeId);if(up.error||ep.error){setUploadStatus((up.error||ep.error).message);return}setUploadStatus("Upload complete. Draft episode is ready.");setTimeout(()=>location.href="podcast-dashboard.html",900)}});upload.findPreviousUploads().then(prev=>{if(prev.length)upload.resumeFromPreviousUpload(prev[0]);upload.start()})}
function setUploadStatus(s){const el=document.getElementById("uploadStatus");if(el)el.textContent=s}
async function live(){const room=new URLSearchParams(location.search).get("room");shell('<section class="section wrap"><span class="eyebrow">REALTIME</span><h2>🔴 LIVE <span class="glow">PODCASTING</span></h2><p>Live listener chat powered by CrowRules + Supabase Realtime.</p><div class="card chat"><div class="messages" id="messages"><div class="msg"><b>CrowRules</b> Welcome to the live room.</div></div><div style="display:flex;gap:8px;margin-top:10px"><input id="chatInput" placeholder="Say something..." style="flex:1"><button class="btn primary" onclick="sendChat()">Send</button></div></div></section>');if(room)initLiveRealtime(room)}
async function sendChat(){const u=await user();if(!u){alert("Log in to join live chat.");return}const v=chatInput.value.trim();if(!v)return;const room=new URLSearchParams(location.search).get("room")||document.body.dataset.room;if(!room){messages.insertAdjacentHTML("beforeend",'<div class="msg"><b>You</b> '+esc(v)+'</div>');chatInput.value="";return}const r=await crSupabase.from("podcast_live_messages").insert({room_id:room,user_id:u.id,message:v});if(r.error){alert(r.error.message);return}chatInput.value=""}
async function initLiveRealtime(room){if(!crSupabase||!room)return;const ch=crSupabase.channel("podcast-live-"+room).on("postgres_changes",{event:"INSERT",schema:"public",table:"podcast_live_messages",filter:"room_id=eq."+room},payload=>{const m=payload.new;if(document.getElementById("messages"))document.getElementById("messages").insertAdjacentHTML("beforeend",'<div class="msg"><b>'+esc(m.user_id)+'</b> '+esc(m.message)+'</div>')}).subscribe();window.__podcastLiveChannel=ch}
async function launch(){shell('<section class="hero"><div class="wrap"><span class="eyebrow">THE COUNTDOWN BEGINS</span><h1>CROWRULES<br><span class="glow">PODCASTING</span></h1><p>Launch date: January 1, 2027</p><div id="countdown" class="count"></div><a class="btn primary" href="signup.html">SIGN UP FOR CROWRULES</a></div></section>');countdown()}
async function resetPassword(){shell('<section class="section wrap"><div class="form"><span class="eyebrow">ACCOUNT RECOVERY</span><h2>RESET <span class="glow">PASSWORD</span></h2><div class="field"><label>Email</label><input id="resetEmail" type="email"></div><button class="btn primary" onclick="sendReset()">SEND RESET LINK</button></div></section>')}
async function sendReset(){const {error}=await crSupabase.auth.resetPasswordForEmail(resetEmail.value,{redirectTo:location.origin+location.pathname.replace("reset-password.html","profile.html")});alert(error?error.message:"Reset link sent. Check your email.")}
async function verify(){const u=await user();shell('<section class="section wrap"><div class="card"><span class="eyebrow">CROWRULES VERIFICATION</span><h2>ACCOUNT <span class="glow">STATUS</span></h2><p>'+esc(u?(u.email_confirmed_at?"Your email is verified.":"Your email still needs verification."):"Log in to check your verification status.")+'</p></div></section>')}
async function crowpoints(){const u=await user();if(!u){location.href="login.html";return}const {data}=await crSupabase.from("crowrules_crowpoints_ledger").select("points,reason,source,created_at").eq("user_id",u.id).order("created_at",{ascending:false}).limit(25);const total=(data||[]).reduce((n,x)=>n+Number(x.points||0),0);shell('<section class="section wrap"><span class="eyebrow">UNIVERSAL REWARDS</span><h2>YOUR <span class="glow">CROWPOINTS</span></h2><div class="card"><h1 class="glow">'+total.toLocaleString()+'</h1><p>Recent activity</p></div><div class="grid">'+(data||[]).map(x=>'<div class="card"><b>'+((x.points>0?"+":"")+Number(x.points).toLocaleString())+'</b><p>'+esc(x.reason)+'</p><small>'+new Date(x.created_at).toLocaleString()+'</small></div>').join("")+'</div></section>')}


async function achievements(){const u=await user();if(!u){location.href="login.html";return}const [s,prof,unlocks]=await Promise.all([crSupabase.from("podcast_member_profile_stats").select("*").eq("user_id",u.id).maybeSingle(),crSupabase.from("podcast_member_profiles").select("display_name,username").eq("user_id",u.id).maybeSingle(),crSupabase.from("podcast_profile_achievement_unlocks").select("achievement_key,unlocked_at").eq("user_id",u.id)]);const x=s.data||{},earned=new Map((unlocks.data||[]).map(a=>[a.achievement_key,a]));const defs=[{key:"first_listen",name:"First Listen",desc:"Listen to your first podcast episode.",icon:"🎧",value:Number(x.total_plays||0),threshold:1},{key:"listener_10",name:"10 Listens",desc:"Reach 10 podcast plays.",icon:"🔥",value:Number(x.total_plays||0),threshold:10},{key:"listener_60",name:"60 Minutes",desc:"Listen for one hour.",icon:"⏱️",value:Number(x.listening_seconds||0),threshold:3600},{key:"commenter_1",name:"Join the Conversation",desc:"Post your first episode comment.",icon:"💬",value:Number(x.episode_comments||0),threshold:1},{key:"reactor_10",name:"Community Voice",desc:"Leave 10 episode reactions.",icon:"❤️",value:Number(x.episode_reactions||0),threshold:10},{key:"creator_1",name:"Creator",desc:"Publish your first podcast episode.",icon:"🎙️",value:Number(x.published_episodes||0),threshold:1},{key:"creator_10",name:"Creator 10",desc:"Publish 10 podcast episodes.",icon:"🚀",value:Number(x.published_episodes||0),threshold:10},{key:"network_10",name:"Network Builder",desc:"Reach 10 member followers.",icon:"🌐",value:Number(x.member_followers||0),threshold:10}];for(const a of defs){if(a.value>=a.threshold&&!earned.has(a.key)){await crSupabase.from("podcast_profile_achievement_unlocks").insert({user_id:u.id,achievement_key:a.key});earned.set(a.key,{achievement_key:a.key,unlocked_at:new Date().toISOString()})}}const unlocked=defs.filter(a=>earned.has(a.key)).length;const html=defs.map(a=>{const ok=earned.has(a.key);const e=earned.get(a.key);return '<article class="card" style="opacity:'+(ok?1:.55)+'"><div style="font-size:2rem">'+a.icon+'</div><span class="eyebrow">'+(ok?"UNLOCKED":"LOCKED")+'</span><h3>'+esc(a.name)+'</h3><p>'+esc(a.desc)+'</p><small>'+Math.min(a.value,a.threshold)+' / '+a.threshold+(e?' · '+new Date(e.unlocked_at).toLocaleDateString():"")+'</small></article>'}).join("");shell('<section class="section wrap"><span class="eyebrow">CROWRULES PROGRESSION</span><h1><span class="glow">ACHIEVEMENTS</span></h1><p>'+esc(prof.data?.display_name||prof.data?.username||"Member")+' · '+unlocked+' of '+defs.length+' unlocked</p><div class="actions"><a class="btn" href="crowpoints.html">CROWPOINTS</a><a class="btn" href="member.html">MEMBER HUB</a></div><div class="grid">'+html+'</div></section>')}

