async function notifications(){const u=await user();if(!u){location.href="login.html";return}const {data}=await crSupabase.from("podcast_notifications").select("*").eq("user_id",u.id).order("created_at",{ascending:false}).limit(50);const unread=(data||[]).filter(n=>!n.is_read).length;shell('<section class="section wrap"><span class="eyebrow">MEMBER ACTIVITY</span><h1><span class="glow">NOTIFICATIONS</span></h1><div class="actions"><button class="btn primary" onclick="markNotificationsRead()">MARK ALL READ</button><button class="btn" onclick="clearNotificationView()">REFRESH</button></div><p><span id="notificationCount" class="pill">'+unread+' unread</span> <span id="notificationLive" class="pill">LIVE UPDATES OFF</span></p><div id="notificationList" class="grid" style="margin-top:25px">'+((data||[]).map(notificationCard).join("")||"<p>You’re all caught up.</p>")+'</div></section>');initNotificationRealtime(u.id)}
function notificationCard(n){const link=n.episode_id?'episode.html?id='+encodeURIComponent(n.episode_id):(n.podcast_id?'podcasts.html?id='+encodeURIComponent(n.podcast_id):'notifications.html');return '<article class="card" data-notification-id="'+esc(n.id)+'" style="'+(n.is_read?'':'border-color:rgba(0,255,255,.55)')+'"><small>'+new Date(n.created_at).toLocaleString()+'</small><h3>'+esc(n.title||n.type||"Notification")+'</h3><p>'+esc(n.body||"")+'</p><div class="actions"><span class="pill">'+(n.is_read?"Read":"New")+'</span><a class="btn" href="'+link+'">'+(n.episode_id||n.podcast_id?"OPEN":"VIEW")+'</a>'+(n.is_read?'':'<button class="btn" onclick="markOneNotification(\''+n.id+'\')">MARK READ</button>')+'</div></article>'}
function initNotificationRealtime(userId){if(window.notificationChannel)crSupabase.removeChannel(window.notificationChannel);window.notificationChannel=crSupabase.channel("podcast-notifications-"+userId).on("postgres_changes",{event:"INSERT",schema:"public",table:"podcast_notifications",filter:"user_id=eq."+userId},payload=>{const list=document.getElementById("notificationList");if(!list)return;const empty=list.querySelector("p");if(empty)empty.remove();list.insertAdjacentHTML("afterbegin",notificationCard(payload.new));const badge=document.getElementById("notificationCount");if(badge){const n=parseInt(badge.textContent)||0;badge.textContent=(n+1)+" unread"}const live=document.getElementById("notificationLive");if(live){live.textContent="LIVE UPDATES ON";live.classList.add("glow")}}).subscribe(status=>{const live=document.getElementById("notificationLive");if(live)live.textContent=status==="SUBSCRIBED"?"LIVE UPDATES ON":"LIVE UPDATES "+status})}
