async function activity(){const u=await user();if(!u){location.href="login.html";return}const {data:mf}=await crSupabase.from("podcast_member_follows").select("followed_user_id").eq("follower_user_id",u.id);const mids=(mf||[]).map(x=>x.followed_user_id);const {data:pf}=await crSupabase.from("podcast_follows").select("podcast_id").eq("user_id",u.id);const pids=(pf||[]).map(x=>x.podcast_id);let html='';const creatorUpdates=await creatorFollowedEpisodes(u,mids);html+=creatorUpdates.html;if(mids.length){const {data:profiles}=await crSupabase.from("podcast_member_profiles").select("user_id,display_name,username").in("user_id",mids).eq("is_public",true);(profiles||[]).forEach(p=>html+='<div class="card"><span class="eyebrow">NETWORK</span><h3>'+esc(p.display_name||p.username||"Member")+'</h3><p>You follow this member.</p><a class="btn" href="member-profile.html?id='+encodeURIComponent(p.user_id)+'">VIEW PROFILE</a></div>')}if(pids.length){const {data:eps}=await crSupabase.from("podcast_episodes").select("id,title,podcast_id,published_at").in("podcast_id",pids).eq("status","published").order("published_at",{ascending:false}).limit(25);(eps||[]).forEach(e=>html+='<div class="card"><span class="eyebrow">NEW EPISODE</span><h3>'+esc(e.title)+'</h3><p>From a podcast you follow.</p><a class="btn primary" href="episode.html?id='+encodeURIComponent(e.id)+'">LISTEN</a></div>')}const {data:notes}=await crSupabase.from("podcast_notifications").select("*").eq("user_id",u.id).order("created_at",{ascending:false}).limit(20);(notes||[]).forEach(n=>html+='<div class="card"><span class="eyebrow">NOTIFICATION</span><h3>'+esc(n.title||"CrowRules Update")+'</h3><p>'+esc(n.body||"")+'</p><small>'+new Date(n.created_at).toLocaleString()+'</small></div>');if(creatorUpdates.podcastIds?.length){crSupabase.channel("creator-activity-"+u.id).on("postgres_changes",{event:"INSERT",schema:"public",table:"podcast_episodes"},async payload=>{const e=payload.new;if(e?.status!=="published"||!creatorUpdates.podcastIds.includes(e.podcast_id))return;const el=document.createElement("div");el.className="card";el.innerHTML='<span class="eyebrow">LIVE CREATOR UPDATE</span><h3>'+esc(e.title||"New episode")+'</h3><p>A creator you follow just published an episode.</p><a class="btn primary" href="episode.html?id='+encodeURIComponent(e.id)+'">LISTEN</a>';document.querySelector(".grid")?.prepend(el)}).subscribe()};shell('<section class="section wrap"><span class="eyebrow">COMMUNITY ACTIVITY</span><h1>YOUR <span class="glow">ACTIVITY</span></h1><p>Updates from the people and podcasts you follow, plus your CrowRules notifications.</p><div class="actions"><a class="btn" href="feed.html">MY FEED</a><a class="btn" href="members.html">NETWORK</a><a class="btn" href="notifications.html">NOTIFICATIONS</a></div><div class="grid">'+(html||'<div class="card"><h3>Your activity feed is ready.</h3><p>Follow podcasts and members to start building your community activity.</p></div>')+'</div></section>')}
